                self.i = (self.i + 1);
                }
                const combinator = ((self.sel.components.items[@as(usize, @intCast(((self.sel.components.items.len - 1) - self.i)))].asCombinator()) orelse continue);
                return combinator;
            }
            return null;
    }
};
const CompoundSelectorIter = struct {
