                    const end = self.i;
                    const slice = self.sel.components.items[((self.sel.components.items.len - 1) - start)..(self.sel.components.items.len - end)];
                    self.i = (combinator_index + 1);
                    return slice;
                }
                const slice = self.sel.components.items[0..(((self.sel.components.items.len - 1) - self.i) + 1)];
                self.i = self.sel.components.items.len;
