pub fn isEquivalent(selectors: []const Selector, other: []const Selector) bool {
        if ((selectors.len != other.len)) {
            return false;
        }
        var i: usize = 0;
        _ = &i;
        while ((i < selectors.len)) {
            const a = (&selectors[@as(usize, @intCast(i))]);
            const b = (&other[@as(usize, @intCast(i))]);
            if ((a.len() != b.len())) {
                return false;
            }
            var j: usize = 0;
            _ = &j;
            while ((j < a.components.items.len)) {
                const a_comp = (&a.components.items[@as(usize, @intCast(j))]);
                const b_comp = (&b.components.items[@as(usize, @intCast(j))]);
                const is_equivalent = blk: {
                if (((a_comp.* == Component.non_ts_pseudo_class) and (b_comp.* == Component.non_ts_pseudo_class))) {
                    break :blk a_comp.non_ts_pseudo_class.isEquivalent((&b_comp.non_ts_pseudo_class));
                } else {
                    if (((a_comp.* == Component.pseudo_element) and (b_comp.* == Component.pseudo_element))) {
                        break :blk a_comp.pseudo_element.isEquivalent((&b_comp.pseudo_element));
                    } else {
                        if ((((((a_comp.* == Component.any) and (b_comp.* == Component.is)) or ((a_comp.* == Component.is) and (b_comp.* == Component.any))) or ((a_comp.* == Component.any) and (b_comp.* == Component.any))) or ((a_comp.* == Component.is) and (b_comp.* == Component.is)))) {
                            const a_selectors = (switch (a_comp.*) {
.any => |v| v.selectors,
.is => |v| v,
else => unreachable,
});
                            const b_selectors = (switch (b_comp.*) {
.any => |v| v.selectors,
.is => |v| v,
else => unreachable,
});
                            break :blk isEquivalent(a_selectors, b_selectors);
                        } else {
                            break :blk Component.eql(a_comp, b_comp);
                        }
                    }
                }
};
                if ((!is_equivalent)) {
                    return false;
                }
                j = (j + 1);
            }
            i = (i + 1);
        }
        return true;
}

pub fn downlevelSelectors(allocator: Allocator, selectors: []Selector, targets: css.targets.Targets) css.VendorPrefix {
        var necessary_prefixes = css.VendorPrefix{  };
