            var list = bun.handleOom(ArrayList(string).initCapacity(allocator, 1));
            _ = &list;
            _ = list.appendAssumeCapacity(langs[@as(usize, @intCast(l_i))]);
            break :langs list;
} } } });
            l_i = (l_i + 1);
        }
        return selectors;
}

pub fn getPrefix(selectors: *const SelectorList) css.VendorPrefix {
        var prefix = css.VendorPrefix{  };
        _ = &prefix;
        var s_i: usize = 0;
        _ = &s_i;
        const sel_slice = selectors.v.slice();
        while ((s_i < sel_slice.len)) {
            const selector = (&sel_slice[@as(usize, @intCast(s_i))]);
            var c_i: usize = 0;
            _ = &c_i;
            while ((c_i < selector.components.items.len)) {
                const component: *const Component = (&selector.components.items[@as(usize, @intCast(c_i))]);
                const p = (switch (component.*) {
.non_ts_pseudo_class => |*pc| (switch (pc.*) {
.lang => css.VendorPrefix{ .none = true },
.dir => css.VendorPrefix{ .none = true },
else => pc.getPrefix(),
}),
.is => css.VendorPrefix{ .none = true },
.where => css.VendorPrefix{ .none = true },
.has => css.VendorPrefix{ .none = true },
.negation => css.VendorPrefix{ .none = true },
.any => |*a| a.vendor_prefix,
.pseudo_element => |*pe| pe.getPrefix(),
else => css.VendorPrefix{  },
});
                if ((!p.isEmpty())) {
                    var prefix_without_none = prefix;
                    _ = &prefix_without_none;
                    prefix_without_none.none = false;
                    if ((prefix_without_none.isEmpty() or (prefix_without_none == p))) {
                        _ = bun.bits.insert(css.VendorPrefix, (&prefix), p);
                    } else {
                        return css.VendorPrefix{  };
                    }
                }
                c_i = (c_i + 1);
            }
            s_i = (s_i + 1);
        }
        return prefix;
}

pub fn isCompatible(selectors: []const parser.Selector, targets: css.targets.Targets) bool {
        const F = css.compat.Feature;
        var s_i: usize = 0;
        _ = &s_i;
        while ((s_i < selectors.len)) {
            const selector = (&selectors[@as(usize, @intCast(s_i))]);
            var c_i: usize = 0;
            _ = &c_i;
            while ((c_i < selector.components.items.len)) {
                const component = (&selector.components.items[@as(usize, @intCast(c_i))]);
                const feature = (switch (component.*) {
.id, .class, .local_name => continue,
.explicit_any_namespace, .explicit_no_namespace, .default_namespace, .namespace => F.namespaces,
.explicit_universal_type => F.selectors2,
.attribute_in_no_namespace_exists => F.selectors2,
.attribute_in_no_namespace => |x| brk: {
                if ((x.case_sensitivity != parser.attrs.ParsedCaseSensitivity.case_sensitive)) {
                    break :brk F.case_insensitive;
                }
                break :brk (switch (x.operator) {
.equal, .includes, .dash_match => F.selectors2,
.prefix, .substring, .suffix => F.selectors3,
});
},
.attribute_other => |attr| (switch (attr.operation) {
.exists => F.selectors2,
.with_value => |*x| brk: {
                if ((x.case_sensitivity != parser.attrs.ParsedCaseSensitivity.case_sensitive)) {
                    break :brk F.case_insensitive;
                }
                break :brk (switch (x.operator) {
.equal, .includes, .dash_match => F.selectors2,
.prefix, .substring, .suffix => F.selectors3,
});
},
}),
.empty, .root => F.selectors3,
.negation => |sels| {
{
                    if (((!targets.isCompatible(F.selectors3)) or (!isCompatible(sels, targets)))) {
                        return false;
                    }
                    continue;
                }
},
.nth => |*data| brk: {
                if ((((data.ty == .child) and (data.a == 0)) and (data.b == 1))) {
                    break :brk F.selectors2;
                }
                if (((data.ty == .col) or (data.ty == .last_col))) {
                    return false;
                }
                break :brk F.selectors3;
},
.nth_of => |*n| {
{
                    if (((!targets.isCompatible(F.nth_child_of)) or (!isCompatible(n.selectors, targets)))) {
                        return false;
                    }
                    continue;
                }
},
.is => |sels| brk: {
                if ((shouldUnwrapIs(sels) and isCompatible(sels, targets))) {
                    continue;
                }
                break :brk F.is_selector;
},
.where, .nesting => F.is_selector,
.any => {
return false;
},
.has => |sels| {
{
                    if (((!targets.isCompatible(F.has_selector)) or (!isCompatible(sels, targets)))) {
                        return false;
                    }
                    continue;
                }
},
.scope, .host, .slotted => F.shadowdomv1,
.part => F.part_pseudo,
.non_ts_pseudo_class => |*pseudo| brk: {
                switch (pseudo.*) {
.link, .visited, .active, .hover, .focus, .lang => {
break :brk F.selectors2;
},
.checked, .disabled, .enabled, .target => {
break :brk F.selectors3;
},
.any_link => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.any_link;
                }
},
.indeterminate => {
break :brk F.indeterminate_pseudo;
},
.fullscreen => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.fullscreen;
                }
},
.focus_visible => {
break :brk F.focus_visible;
},
.focus_within => {
break :brk F.focus_within;
},
.default => {
break :brk F.default_pseudo;
},
.dir => {
break :brk F.dir_selector;
},
.optional => {
break :brk F.optional_pseudo;
},
.placeholder_shown => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.placeholder_shown;
                }
},
inline .read_only, .read_write => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.read_only_write;
                }
},
.valid, .invalid, .required => {
break :brk F.form_validation;
},
.in_range, .out_of_range => {
break :brk F.in_out_of_range;
},
.autofill => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.autofill;
                }
},
.current, .past, .future, .playing, .paused, .seeking, .stalled, .buffering, .muted, .volume_locked, .target_within, .local_link, .blank, .user_invalid, .user_valid, .defined => {
return false;
},
.custom => {

},
else => {

},
}
                return false;
},
.pseudo_element => |*pseudo| brk: {
                switch (pseudo.*) {
.after, .before => {
break :brk F.gencontent;
},
.first_line => {
break :brk F.first_line;
},
.first_letter => {
break :brk F.first_letter;
},
.selection => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.selection;
                }
},
.placeholder => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.placeholder;
                }
},
.marker => {
break :brk F.marker_pseudo;
},
.backdrop => |prefix| {
if ((prefix == css.VendorPrefix{ .none = true })) {
                    break :brk F.dialog;
                }
},
.cue => {
break :brk F.cue;
},
.cue_function => {
break :brk F.cue_function;
},
.custom => {
return false;
},
else => {

},
}
                return false;
},
.combinator => |*combinator| brk: {
                break :brk (switch (combinator.*) {
.child, .next_sibling => F.selectors2,
.later_sibling => F.selectors3,
else => continue,
});
},
});
                if ((!targets.isCompatible(feature))) {
                    return false;
                }
                c_i = (c_i + 1);
            }
            s_i = (s_i + 1);
        }
        return true;
}

pub fn isUnused(selectors: []const parser.Selector, unused_symbols: *const std.StringArrayHashMapUnmanaged(void), symbols: *const css.SymbolList, parent_is_unused: bool) bool {
        if ((unused_symbols.count() == 0)) {
            return false;
        }
        var s_i: usize = 0;
        _ = &s_i;
        while ((s_i < selectors.len)) {
            const selector = (&selectors[@as(usize, @intCast(s_i))]);
            if ((!isSelectorUnused(selector, unused_symbols, symbols, parent_is_unused))) {
                return false;
            }
            s_i = (s_i + 1);
        }
        return true;
}

pub fn isSelectorUnused(selector: *const parser.Selector, unused_symbols: *const std.StringArrayHashMapUnmanaged(void), symbols: *const css.SymbolList, parent_is_unused: bool) bool {
        var c_i: usize = 0;
        _ = &c_i;
        while ((c_i < selector.components.items.len)) {
            const component = (&selector.components.items[@as(usize, @intCast(c_i))]);
            switch (component.*) {
.class, .id => |ident| {
const actual_ident = ident.asOriginalString(symbols);
            if (unused_symbols.contains(actual_ident)) {
                return true;
            }
},
.is, .where => |is| {
if (isUnused(is, unused_symbols, symbols, parent_is_unused)) {
                return true;
            }
},
.any => |a| {
if (isUnused(a.selectors, unused_symbols, symbols, parent_is_unused)) {
                return true;
            }
},
.nesting => {
if (parent_is_unused) {
                return true;
            }
},
else => {

},
}
            c_i = (c_i + 1);
        }
        return false;
}

pub fn shouldUnwrapIs(selectors: []const parser.Selector) bool {
        if ((selectors.len == 1)) {
            const first = selectors[0];
            if (((!hasTypeSelector((&first))) and isSimple((&first)))) {
                return true;
            }
        }
        return false;
}

pub fn hasTypeSelector(selector: *const parser.Selector) bool {
        var iter = selector.iterRawMatchOrder();
        _ = &iter;
        var first = iter.next();
        _ = &first;
        if (isNamespace(first)) {
            return isTypeSelector(iter.next());
        }
        return isTypeSelector(first);
}

pub fn isNamespace(component: ?parser.Component) bool {
        if (component) |c| {
            _ = &c;
            return (switch (c) {
.explicit_any_namespace, .explicit_no_namespace, .namespace, .default_namespace => true,
else => false,
});
        }
        return false;
}

pub fn isTypeSelector(component: ?parser.Component) bool {
        if (component) |c| {
            _ = &c;
            return (switch (c) {
.local_name, .explicit_universal_type => true,
else => false,
});
        }
        return false;
}

pub fn isSimple(selector: *const parser.Selector) bool {
        var iter = selector.iterRawParseOrderFrom(0);
        _ = &iter;
        while (iter.next()) |component| {
            if (component.isCombinator()) {
                return false;
            }
        }
        return true;
}
